import type { RerailDatabase } from "../storage/database.js";

/**
 * Databases known to hold `audit_unlisted_failures`. A read-only open applies no DDL, so a file only an earlier build
 * wrote lacks the table: its audits list every failure they kept, and none is counted beyond them.
 */
const HOLDS_UNLISTED_TABLE = new WeakSet<RerailDatabase>();
function holdsUnlistedTable(database: RerailDatabase): boolean {
  if (HOLDS_UNLISTED_TABLE.has(database)) return true;
  const holds = database.$client
    .prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'audit_unlisted_failures'")
    .get() !== undefined;
  if (holds) HOLDS_UNLISTED_TABLE.add(database);
  return holds;
}

import { eq, sql } from "drizzle-orm";
import { setupReviews } from "../storage/schema.js";

export function setupReviewOffered(db: Reader, repositoryKey: RepositoryKey): boolean {
  const kept = db.get<{ name: string } | undefined>(sql`SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'setup_reviews'`);
  if (kept === undefined) return false;
  return db.select({ key: setupReviews.repositoryKey }).from(setupReviews)
    .where(eq(setupReviews.repositoryKey, repositoryKey)).get() !== undefined;
}

import { getTableName, sql } from "drizzle-orm";
import { checkouts, repositories } from "../engine/storage/schema.js";

const START_TABLES = [getTableName(repositories), getTableName(checkouts)];

function hasStartTables(database: Pick<RerailDatabase, "all">): boolean {
  const names = sql.join(START_TABLES.map(name => sql`${name}`), sql`, `);
  return database.all(sql`SELECT name FROM sqlite_master WHERE type = 'table' AND name IN (${names})`).length === START_TABLES.length;
}

import { sql } from "drizzle-orm";

export function hasSessionsTable(database: RerailDatabase): boolean {
  return database.all(sql`SELECT 1 FROM sqlite_schema WHERE type = 'table' AND name = 'sessions'`).length > 0;
}

export function holdsRuleSettings(database: RerailDatabase): boolean {
  return database.$client.prepare("PRAGMA main.table_list('rule_settings')").all().length > 0;
}

import { sql } from "drizzle-orm";

export function holdsLibraryRules(db: Reader): boolean {
  return db.all(sql`SELECT name FROM pragma_table_list WHERE name = 'library_rules'`).length > 0;
}

export function holdsRuleSettings(database: RerailDatabase): boolean {
  return database.$client.pragma("table_list(rule_settings)").length > 0;
}

import { sql } from "drizzle-orm";

export function keepsSetupReviews(db: Reader): boolean {
  return db.all(sql`SELECT name FROM pragma_table_info(${"setup_reviews"})`).length > 0;
}

export function holdsRuleSettings(database: RerailDatabase): boolean {
  return database.$client.prepare('PRAGMA "main".table_list(rule_settings)').all().length > 0;
}

export function workspaceStarted(database: RerailDatabase, workspace: string): boolean {
  try {
    return checkoutStatus(database, lookupCheckout(database, workspace)).started;
  } catch (error) {
    if (error instanceof Error && error.message.includes("no such table")) return false;
    throw error;
  }
}

