import { eq } from "drizzle-orm";
import { tableExists } from "../storage/database.js";
import { setupReviews } from "../storage/schema.js";

export function setupReviewOffered(db: Reader, repositoryKey: RepositoryKey): boolean {
  if (!tableExists(db, setupReviews)) return false;
  return db.select({ key: setupReviews.repositoryKey }).from(setupReviews)
    .where(eq(setupReviews.repositoryKey, repositoryKey)).get() !== undefined;
}

import { auditRows } from "./audit-rows.js";

/**
 * A file only older builds wrote has no audit_unlisted_failures table; sqlite_master would not list it, and storage
 * reports that before this runs.
 */
export function auditCount(db: Reader): number {
  return auditRows(db).length;
}

export function unreadable(path: string): Error {
  return new Error(`${path} lists no checkouts table in sqlite_master; run a rerail command to finish creating it.`);
}

const MESSAGE = "Rerail could not read the audits table";
const sqliteMasterRows = 0;
export function describe(): string { return `${MESSAGE} (${sqliteMasterRows})`; }

function missingSchemaObjects(database: RerailDatabase): string[] {
  const present = new Set(database.all<{ name: string }>(sql`SELECT name FROM sqlite_master`).map(row => row.name));
  return SCHEMA_OBJECTS.filter(name => !present.has(name));
}
